package com.franco.desco.adapter.in.web.production;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.production.*;import com.franco.desco.application.production.port.in.ProductionUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController@RequestMapping("/api/v1/produccion")@Tag(name="Producción disponible",description="Estimaciones y confirmación de disponibilidad productiva.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class ProductionController{private final ProductionUseCase u;private final ProductionWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public ProductionController(ProductionUseCase u,ProductionWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping@PreAuthorize("@permissionGuard.has(authentication,'PRODUCCION_LISTAR')")@Operation(operationId="produccionListar",summary="Listar producción disponible")public ResponseEntity<ApiResponse<PageResponse<ProductionResponses.Summary>>>list(@RequestParam(required=false)String estadoEstimacion,@RequestParam(required=false)Long zonaProductivaId,@RequestParam(required=false)Long predioId,@RequestParam(required=false)Long socioId,@RequestParam(required=false)Long asociacionId,@RequestParam(required=false)Integer variedadPaltaId,@RequestParam(required=false)String origen,@RequestParam(required=false)LocalDate disponibleDesde,@RequestParam(required=false)LocalDate disponibleHasta,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,estadoEstimacion,zonaProductivaId,predioId,socioId,asociacionId,variedadPaltaId,origen,disponibleDesde,disponibleHasta),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}")@PreAuthorize("@permissionGuard.has(authentication,'PRODUCCION_VER')")@Operation(operationId="produccionVer",summary="Ver estimación de producción")public ResponseEntity<ApiResponse<ProductionResponses.Detail>>get(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.get(new ProductionCommands.Get(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'PRODUCCION_CREAR')")@Operation(operationId="produccionCrear",summary="Registrar estimación")public ResponseEntity<ApiResponse<ProductionResponses.Created>>create(@Valid@RequestBody ProductionRequests.Create q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.create(new ProductionCommands.Create(q.parcelaCultivoId(),q.visitaTecnicaId(),q.fechaEstimacion(),q.disponibleDesde(),q.disponibleHasta(),q.cantidadEstimadaKg(),q.observacion()),ids.resolve(a),meta.resolve(r)),r,ProductionResponses.Created::new);}
 @PutMapping("/{id}")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'PRODUCCION_EDITAR')")@Operation(operationId="produccionEditar",summary="Editar estimación")public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid@RequestBody ProductionRequests.Update q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.update(new ProductionCommands.Update(id,q.disponibleDesde(),q.disponibleHasta(),q.cantidadEstimadaKg(),q.observacion()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/confirmar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'PRODUCCION_CONFIRMAR')")@Operation(operationId="produccionConfirmar",summary="Confirmar producción disponible")public ResponseEntity<ApiResponse<Void>>confirm(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.confirm(new ProductionCommands.Confirm(id),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/descartar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'PRODUCCION_RETIRAR')")@Operation(operationId="produccionDescartar",summary="Descartar estimación")public ResponseEntity<ApiResponse<Void>>discard(@PathVariable Long id,@Valid@RequestBody ProductionRequests.Discard q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.discard(new ProductionCommands.Discard(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}}
